package dev.genericpayments.platform.payments.application.service;
import static org.assertj.core.api.Assertions.*;
import dev.genericpayments.platform.payments.application.port.in.*;
import dev.genericpayments.platform.payments.application.port.out.*;
import dev.genericpayments.platform.payments.application.model.*;
import dev.genericpayments.platform.payments.domain.*;
import dev.genericpayments.platform.shared.application.PaymentApplicationException;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.util.function.Function;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
@SpringBootTest(properties="payment.telemetry.site-keys[0]=test-site")
class RefundCoordinatorIntegrationTest extends ProviderTestFixture {
 @Autowired RefundCoordinator refunds;
 @Autowired LoadRefundPort refundLoad;
 @Autowired ProviderInboxWorker worker;
 final UUID actor=UUID.fromString("30000000-0000-0000-0000-000000000001");
 Payment paid(){var p=save.save(payment());fake.preparePayment(request(p));return save.save(p.withProviderPaymentReference("fake_pi_"+p.id().value(),INITIAL_TIME).succeeded(INITIAL_TIME));}
 CreateRefundCommand command(Payment p,long amount,String key){return new CreateRefundCommand(site,p.id(),actor,amount,"EUR","REQUESTED_BY_CUSTOMER",null,key,"request-9");}
 @Test void partialReservationReplayAndConflict(){var p=paid();var r=refunds.create(command(p,700,"one"));assertThat(r.status()).isEqualTo(RefundStatus.PROCESSING);assertThat(refunds.create(command(p,700,"one")).id()).isEqualTo(r.id());assertThat(count("refunds")).isEqualTo(1);assertThat(count("idempotency_records")).isEqualTo(1);assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();assertThat(events.findByPayment(site,p.id())).extracting(PaymentEvent::type).containsExactly(PaymentEventType.REFUND_REQUESTED,PaymentEventType.REFUND_PROCESSING);assertThatThrownBy(()->refunds.create(command(p,701,"one"))).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("IDEMPOTENCY_CONFLICT");}
 @Test void concurrentRefundsCannotReserveMoreThanPaidAmount()throws Exception {var p=paid();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);Callable<Boolean> a=()->{gate.await();try{refunds.create(command(p,1400,UUID.randomUUID().toString()));return true;}catch(PaymentApplicationException e){assertThat(e.code()).isEqualTo("REFUND_EXCEEDS_AVAILABLE");return false;}};var one=pool.submit(a);var two=pool.submit(a);gate.countDown();assertThat(List.of(one.get(10,TimeUnit.SECONDS),two.get(10,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}assertThat(count("refunds")).isEqualTo(1);}
 @Test void fullRefundRemainsUnconfirmedUntilInboxAndDuplicatesAreNoops(){var p=paid();var r=refunds.create(command(p,2000,"full"));assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.SUCCEEDED);var ref=r.providerRefundReference();receive(new ProviderEventEnvelope(account.provider(),account.id(),"refund-event",ref,PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.REFUNDED);assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isEqualTo(2000);receive(new ProviderEventEnvelope(account.provider(),account.id(),"late-failed",ref,PaymentEventType.REFUND_FAILED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(refundLoad.findById(site,r.id()).orElseThrow().value().status()).isEqualTo(RefundStatus.SUCCEEDED);assertThat(events.findByPayment(site,p.id())).hasSize(3);}
 @Autowired ProviderInboxService admission;
 void receive(ProviderEventEnvelope e){admission.receive(e);}
 @Test void currencyAndUnpaidStateFailBeforeReservation(){var p=paid();assertThatThrownBy(()->refunds.create(new CreateRefundCommand(site,p.id(),actor,1,"USD","REQUESTED_BY_CUSTOMER",null,"currency","request"))).isInstanceOf(PaymentApplicationException.class);assertThatThrownBy(()->refunds.create(command(save.save(payment()),1,"unpaid"))).isInstanceOf(PaymentApplicationException.class);assertThat(count("refunds")).isZero();assertThat(count("idempotency_records")).isZero();}
 @Autowired PaymentTransitionPort tx;@Autowired SaveRefundPort refundSave;
 @Autowired dev.genericpayments.platform.sites.application.port.out.LoadSitePort sites;
 @Autowired dev.genericpayments.platform.paymentaccounts.application.port.out.LoadPaymentAccountPort accounts;
 @Autowired IdempotencyService idem;@Autowired AppendPaymentEventPort journal;@Autowired AdminPaymentAuditPort audit;
 @Autowired RefundTransitionService refundTransitions;@Autowired PaymentTransitionService paymentTransitions;
 @Autowired dev.genericpayments.platform.shared.application.port.out.Stage2TelemetryPort telemetry;
 @Autowired java.time.Clock clock;@Autowired io.micrometer.core.instrument.MeterRegistry meters;
 double metric(String name){return meters.find(name).counters().stream().mapToDouble(io.micrometer.core.instrument.Counter::count).sum();}
 PaymentProviderPort provider(Function<ProviderRefundRequest,ProviderResult> call){return new PaymentProviderPort(){public PaymentProviderCapabilities capabilities(dev.genericpayments.platform.paymentaccounts.domain.PaymentAccount a){return fake.capabilities(a);}public ProviderResult preparePayment(ProviderPaymentRequest r){return fake.preparePayment(r);}public ProviderResult confirmPayment(ProviderConfirmationRequest r){return fake.confirmPayment(r);}public ProviderResult requestRefund(ProviderRefundRequest r){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return call.apply(r);}public ProviderState retrievePayment(ProviderPaymentLookup r){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return fake.retrievePayment(r);}public ProviderState retrieveRefund(ProviderRefundLookup r){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return fake.retrieveRefund(r);}};}
 RefundCoordinator coordinator(PaymentProviderPort provider){return new RefundCoordinator(tx,load,refundLoad,refundSave,sites,accounts,new PaymentProviderRegistry(Map.of(account.provider(),provider)),idem,journal,audit,refundTransitions,telemetry,clock);}
 @ParameterizedTest @ValueSource(strings={"ACCEPTED","PROCESSING","RECOVERABLE_DECLINE","TERMINAL_DECLINE","TEMPORARILY_UNAVAILABLE","UNKNOWN"})
 void closedAcknowledgementsNeverConfirmPayment(String kind){var p=paid();var c=coordinator(provider(r->switch(kind){case "ACCEPTED"->new ProviderResult.Accepted("refund-ref",false);case "PROCESSING"->new ProviderResult.Accepted("refund-ref",true);case "RECOVERABLE_DECLINE"->new ProviderResult.RecoverableDecline("refund-ref");case "TERMINAL_DECLINE"->new ProviderResult.TerminalDecline("refund-ref");case "TEMPORARILY_UNAVAILABLE"->new ProviderResult.TemporarilyUnavailable();default->new ProviderResult.Unknown(null);}));var r=c.create(command(p,2000,"ack"));assertThat(r.status().name()).isEqualTo(switch(kind){case "ACCEPTED"->"PENDING";case "PROCESSING"->"PROCESSING";case "UNKNOWN"->"UNKNOWN";default->"FAILED";});assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.SUCCEEDED);assertThat(count("payment_events")).isEqualTo(kind.equals("ACCEPTED")?1:2);}
 @Test void unknownWithoutReferenceReplaysSameOperationAndCrashReservationResumes(){var p=paid();var calls=new AtomicInteger();var keys=new ArrayList<String>();var c=coordinator(provider(r->{keys.add(r.operationKey());if(calls.getAndIncrement()==0)throw new AssertionError("simulated interruption");return new ProviderResult.Unknown(null);}));assertThatThrownBy(()->c.create(command(p,700,"crash"))).isInstanceOf(AssertionError.class);assertThat(count("refunds")).isEqualTo(1);assertThat(count("payment_events")).isEqualTo(1);var r=c.create(command(p,700,"crash"));assertThat(r.status()).isEqualTo(RefundStatus.UNKNOWN);assertThat(c.create(command(p,700,"crash")).id()).isEqualTo(r.id());assertThat(keys).hasSize(3).containsOnly(ProviderOperationKeys.refund(r.id()));assertThat(count("refunds")).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_REFUND_REQUESTED'",Integer.class)).isEqualTo(1);}
 @Test void sameKeyConcurrentFirstRequestsReserveOnce()throws Exception{var p=paid();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);Callable<Refund> call=()->{gate.await();return refunds.create(command(p,700,"same"));};var a=pool.submit(call);var b=pool.submit(call);gate.countDown();assertThat(a.get(10,TimeUnit.SECONDS).id()).isEqualTo(b.get(10,TimeUnit.SECONDS).id());}assertThat(count("refunds")).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_REFUND_REQUESTED'",Integer.class)).isEqualTo(1);}
 @ParameterizedTest @ValueSource(strings={"PENDING","PROCESSING","UNKNOWN","SUCCEEDED"})
 void allReservedStatesCountExactlyOnce(String status){var p=paid();var id=new RefundId(UUID.randomUUID());var r=Refund.request(id,p,dev.genericpayments.platform.catalog.domain.Money.of(1200,"EUR"),ProviderOperationKeys.refund(id),"OTHER",null,INITIAL_TIME);r=switch(status){case "PROCESSING"->r.processing(INITIAL_TIME);case "UNKNOWN"->r.unknown(INITIAL_TIME);case "SUCCEEDED"->r.succeeded(INITIAL_TIME);default->r;};refundSave.insert(r);if(status.equals("SUCCEEDED"))save.save(p.refundSucceeded(1200,INITIAL_TIME));assertThatThrownBy(()->refunds.create(command(p,801,"over"))).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("REFUND_EXCEEDS_AVAILABLE");assertThat(refunds.create(command(p,800,"remaining")).money().minorUnits()).isEqualTo(800);}
 @Test void requestedExactRefundFactIsProcessedNoopIncludingDuplicates(){var p=paid();var r=coordinator(provider(q->new ProviderResult.Accepted("pending-ref",false))).create(command(p,700,"pending"));var before=refundLoad.findById(site,r.id()).orElseThrow();double result=metric("payment.refund.result");for(var id:List.of("requested","requested","repeat"))receive(new ProviderEventEnvelope(account.provider(),account.id(),id,"pending-ref",PaymentEventType.REFUND_REQUESTED,INITIAL_TIME,INITIAL_TIME,Map.of("payment_id",p.id().value().toString(),"refund_id",r.id().value().toString(),"state","REQUESTED","schema_version",1)));worker.runOnce();assertThat(refundLoad.findById(site,r.id()).orElseThrow()).isEqualTo(before);assertThat(jdbc.queryForList("select status from provider_inbox",String.class)).containsOnly("PROCESSED");assertThat(count("payment_events")).isEqualTo(1);assertThat(metric("payment.refund.result")-result).isZero();}
 @Test void partialThenFullSuccessAndLateProcessingAreMonotone(){var p=paid();var one=refunds.create(command(p,700,"partial"));receive(new ProviderEventEnvelope(account.provider(),account.id(),"partial",one.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.PARTIALLY_REFUNDED);var two=refunds.create(command(p,1300,"remaining"));receive(new ProviderEventEnvelope(account.provider(),account.id(),"full",two.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();receive(new ProviderEventEnvelope(account.provider(),account.id(),"late",one.providerRefundReference(),PaymentEventType.REFUND_PROCESSING,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isEqualTo(2000);assertThat(count("payment_events")).isEqualTo(6);}
 @Test void failedRefundReleasesReservationAndFirstTerminalWins(){var p=paid();var r=refunds.create(command(p,2000,"failed"));receive(new ProviderEventEnvelope(account.provider(),account.id(),"fail",r.providerRefundReference(),PaymentEventType.REFUND_FAILED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();receive(new ProviderEventEnvelope(account.provider(),account.id(),"late-success",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();assertThat(refunds.create(command(p,2000,"replacement")).status()).isEqualTo(RefundStatus.PROCESSING);}
 @Test void refundInboxMetricsIncludeReceivedDuplicatesAndOnlyCommittedResults(){var p=paid();var r=refunds.create(command(p,700,"metric"));double received=metric("payment.inbox.received"),duplicate=metric("payment.inbox.duplicate"),result=metric("payment.refund.result");var e=new ProviderEventEnvelope(account.provider(),account.id(),"metric",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of());receive(e);receive(e);worker.runOnce();assertThat(metric("payment.inbox.received")-received).isEqualTo(1);assertThat(metric("payment.inbox.duplicate")-duplicate).isEqualTo(1);assertThat(metric("payment.refund.result")-result).isEqualTo(1);}
 @ParameterizedTest @ValueSource(strings={"Basic dXNlcjpwYXNzd29yZA==","NL91ABNA0417164300","password=hunter2","token=secret"})
 void technicalNotesRejectAuthorizationAndInstrumentData(String note){assertThatThrownBy(()->new CreateRefundCommand(site,new PaymentId(UUID.randomUUID()),actor,100,"EUR","OTHER",note,"key","request")).isInstanceOf(RuntimeException.class);}
 @Test void refundReconciliationUsesProviderTruthAndDoesNotRepeatKnownTerminal(){var p=paid();var r=refunds.create(command(p,700,"reconcile"));jdbc.update("update fake_provider_objects set state='SUCCEEDED' where provider_reference=?",r.providerRefundReference());var probe=provider(fake::requestRefund);var service=new ReconcilePaymentService(paymentTransitions,new PaymentProviderRegistry(Map.of(account.provider(),probe)),telemetry,clock,Duration.ofSeconds(30));service.refunds(refundLoad,refundTransitions,refunds);service.reconcile(site,p.id(),"reconcile");assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isEqualTo(700);int journal=count("payment_events");service.reconcile(site,p.id(),"repeat");assertThat(count("payment_events")).isEqualTo(journal);}
 void callback(){UUID secret=UUID.randomUUID();jdbc.update("insert into site_callback_secret_versions(id,site_id,secret_version,ciphertext,nonce,master_key_version,created_at) values (?,?,1,?,?,'test-v1',?)",secret,site.value(),new byte[32],new byte[12],java.sql.Timestamp.from(INITIAL_TIME));jdbc.update("insert into site_callback_configs(site_id,endpoint_url,active_secret_version_id,enabled,created_at,updated_at) values (?,'https://callback.test/exact',?,true,?,?)",site.value(),secret,java.sql.Timestamp.from(INITIAL_TIME),java.sql.Timestamp.from(INITIAL_TIME));}
 @Test void callbacksUseRefundEventTypeAndAmountNotPaymentStatus(){var p=paid();callback();var r=refunds.create(command(p,700,"callback"));assertThat(jdbc.queryForList("select callback_type from outbox_events",String.class)).containsExactly("refund.processing");String processing=jdbc.queryForObject("select payload::text from outbox_events",String.class);assertThat(processing).contains("SUCCEEDED","700","refund.processing").doesNotContain("provider","metadata","secret","callback.test");receive(new ProviderEventEnvelope(account.provider(),account.id(),"success",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(jdbc.queryForList("select callback_type from outbox_events",String.class)).containsExactlyInAnyOrder("refund.processing","refund.succeeded");assertThat(jdbc.queryForObject("select payload::text from outbox_events where callback_type='refund.succeeded'",String.class)).contains("PARTIALLY_REFUNDED","700");}
 @ParameterizedTest @ValueSource(strings={"refunds","payments","payment_events","outbox_events","provider_inbox"})
 void everyRefundKernelWriteFailureRollsBackAndRetries(String table){var p=paid();var r=refunds.create(command(p,700,"rollback"));callback();var before=refundLoad.findById(site,r.id()).orElseThrow();double result=metric("payment.refund.result");receive(new ProviderEventEnvelope(account.provider(),account.id(),"rollback",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));jdbc.execute("create function task9_reject() returns trigger language plpgsql as $$ begin if TG_TABLE_NAME<>'provider_inbox' or new.status='PROCESSED' then raise exception 'injected failure'; end if; return new; end; $$");jdbc.execute("create trigger task9_reject before insert or update on "+table+" for each row execute function task9_reject()");try{worker.runOnce();assertThat(refundLoad.findById(site,r.id()).orElseThrow()).isEqualTo(before);assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();assertThat(count("payment_events")).isEqualTo(2);assertThat(count("outbox_events")).isZero();assertThat(metric("payment.refund.result")-result).isZero();assertThat(jdbc.queryForObject("select status from provider_inbox",String.class)).isEqualTo("FAILED");}finally{jdbc.execute("drop trigger task9_reject on "+table);jdbc.execute("drop function task9_reject()");}dev.genericpayments.platform.support.PostgresIntegrationTest.TestClock.set(INITIAL_TIME.plusSeconds(5));worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isEqualTo(700);assertThat(count("payment_events")).isEqualTo(3);assertThat(count("outbox_events")).isEqualTo(1);}
 @Test void requestedUnknownAndReplayTelemetryAreExactlyCommitted(){var p=paid();double requested=metric("payment.refund.requested"),result=metric("payment.refund.result");var c=coordinator(provider(r->new ProviderResult.Unknown("unknown-ref")));var r=c.create(command(p,700,"metric"));c.create(command(p,700,"metric"));assertThat(metric("payment.refund.requested")-requested).isEqualTo(1);assertThat(metric("payment.refund.result")-result).isEqualTo(1);assertThat(r.status()).isEqualTo(RefundStatus.UNKNOWN);}
 @Test void unconfiguredTelemetryAndAmbientTransactionRejectBeforeReservation(){var p=paid();var guarded=new dev.genericpayments.platform.shared.adapter.out.observability.MicrometerStage2TelemetryAdapter(new io.micrometer.core.instrument.simple.SimpleMeterRegistry(),Set.of());var c=new RefundCoordinator(tx,load,refundLoad,refundSave,sites,accounts,new PaymentProviderRegistry(Map.of(account.provider(),fake)),idem,journal,audit,refundTransitions,guarded,clock);assertThatThrownBy(()->c.create(command(p,100,"unknown-site"))).isInstanceOf(PaymentApplicationException.class);tx.transaction(()->{assertThatThrownBy(()->refunds.create(command(p,100,"ambient"))).isInstanceOf(IllegalStateException.class);return null;});assertThat(count("refunds")).isZero();assertThat(count("idempotency_records")).isZero();}
 @Test void unknownWithoutReferenceReconciliationRepeatsOnlyOriginalOperation(){var p=paid();var calls=new AtomicInteger();var keys=new ArrayList<String>();var probe=new DelegatingProvider(fake){@Override public ProviderResult requestRefund(ProviderRefundRequest request){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();keys.add(request.operationKey());return calls.getAndIncrement()==0?new ProviderResult.Unknown(null):fake.requestRefund(request);}@Override public ProviderState retrieveRefund(ProviderRefundLookup lookup){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new ProviderState(lookup.reference(),ProviderState.Status.SUCCEEDED);}};var c=coordinator(probe);var r=c.create(command(p,700,"unknown"));assertThat(r.providerRefundReference()).isNull();var service=new ReconcilePaymentService(paymentTransitions,new PaymentProviderRegistry(Map.of(account.provider(),probe)),telemetry,clock,Duration.ofSeconds(30));service.refunds(refundLoad,refundTransitions,c);service.reconcile(site,p.id(),"reconcile");assertThat(keys).hasSize(2).containsOnly(ProviderOperationKeys.refund(r.id()));assertThat(count("refunds")).isEqualTo(1);assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isEqualTo(700);}
 @Test void mismatchedPayloadAndAmbiguousRefundReferenceFailClosed(){var p=paid();var r=refunds.create(command(p,700,"one"));receive(new ProviderEventEnvelope(account.provider(),account.id(),"wrong-payload",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of("refund_id",UUID.randomUUID().toString())));worker.runOnce();assertThat(jdbc.queryForObject("select error_category from provider_inbox",String.class)).isEqualTo("IDENTITY_MISMATCH");var two=refunds.create(command(p,700,"two"));jdbc.update("update refunds set provider_refund_reference=? where id=?",r.providerRefundReference(),two.id().value());receive(new ProviderEventEnvelope(account.provider(),account.id(),"ambiguous",r.providerRefundReference(),PaymentEventType.REFUND_SUCCEEDED,INITIAL_TIME,INITIAL_TIME,Map.of()));worker.runOnce();assertThat(jdbc.queryForObject("select error_category from provider_inbox where provider_event_id='ambiguous'",String.class)).isEqualTo("UNRESOLVED_OBJECT");assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();}
 @Test void replayFingerprintIncludesPaymentReasonAndSafeNote(){var p=paid();var other=paid();refunds.create(command(p,100,"changed"));for(var c:List.of(command(other,100,"changed"),new CreateRefundCommand(site,p.id(),actor,100,"EUR","OTHER",null,"changed","request"),new CreateRefundCommand(site,p.id(),actor,100,"EUR","REQUESTED_BY_CUSTOMER","safe-note","changed","request")))assertThatThrownBy(()->refunds.create(c)).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("IDEMPOTENCY_CONFLICT");assertThat(count("refunds")).isEqualTo(1);}
 @Test void replacementProviderReferenceIsStableSafeConflict(){var p=paid();var calls=new AtomicInteger();var c=coordinator(provider(r->new ProviderResult.Accepted(calls.getAndIncrement()==0?"first-ref":"replacement-ref",false)));var r=c.create(command(p,100,"ref"));assertThatThrownBy(()->c.create(command(p,100,"ref"))).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("PAYMENT_STATE_CONFLICT");assertThat(refundLoad.findById(site,r.id()).orElseThrow().value().providerRefundReference()).isEqualTo("first-ref");}
 @Test void mismatchedPaymentTruthCannotAdvanceOwnedRefund(){var p=paid();var r=refunds.create(command(p,700,"identity"));var calls=new AtomicInteger();var probe=new DelegatingProvider(fake){@Override public ProviderState retrievePayment(ProviderPaymentLookup lookup){return new ProviderState("wrong-payment",ProviderState.Status.SUCCEEDED);}@Override public ProviderState retrieveRefund(ProviderRefundLookup lookup){calls.incrementAndGet();return new ProviderState(lookup.reference(),ProviderState.Status.SUCCEEDED);}};var service=new ReconcilePaymentService(paymentTransitions,new PaymentProviderRegistry(Map.of(account.provider(),probe)),telemetry,clock,Duration.ofSeconds(30));service.refunds(refundLoad,refundTransitions,refunds);assertThatThrownBy(()->service.reconcile(site,p.id(),"identity")).isInstanceOf(PaymentApplicationException.class);assertThat(calls.get()).isZero();assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();assertThat(refundLoad.findById(site,r.id()).orElseThrow().value().status()).isEqualTo(RefundStatus.PROCESSING);}
 @Autowired AdminPaymentReadPort reads;
 AdminReconciliationService adminReconcile(PaymentProviderPort probe){var registry=new PaymentProviderRegistry(Map.of(account.provider(),probe));var service=new ReconcilePaymentService(paymentTransitions,registry,telemetry,clock,Duration.ofSeconds(30));service.refunds(refundLoad,refundTransitions,refunds);return new AdminReconciliationService(reads,tx,idem,audit,service,sites,accounts,registry,telemetry);}
 @Test void reconciliationOrdinaryProviderFailureLeavesCompletedImmutableResumableReceipt(){var p=paid();var calls=new AtomicInteger();var probe=new DelegatingProvider(fake){@Override public ProviderState retrievePayment(ProviderPaymentLookup lookup){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();if(calls.getAndIncrement()==0)throw new IllegalStateException("private provider credentials");return fake.retrievePayment(lookup);}};var service=adminReconcile(probe);assertThatThrownBy(()->service.reconcile(p.id(),actor,"failure","request")).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("PROVIDER_TEMPORARILY_UNAVAILABLE");var receipt=jdbc.queryForMap("select * from idempotency_records");assertThat(receipt.get("status")).isEqualTo("COMPLETED");assertThat(receipt.get("response_status")).isEqualTo(202);assertThatThrownBy(()->service.reconcile(p.id(),actor,"failure","request")).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("PAYMENT_STATE_CONFLICT");dev.genericpayments.platform.support.PostgresIntegrationTest.TestClock.set(INITIAL_TIME.plusSeconds(31));service.reconcile(p.id(),actor,"failure","request");assertThat(jdbc.queryForMap("select * from idempotency_records")).isEqualTo(receipt);assertThat(calls.get()).isEqualTo(2);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_RECONCILIATION_REQUESTED'",Integer.class)).isEqualTo(1);}
 @Test void reconciliationCrashAndConcurrentReplayCannotCreateParallelProviderCalls()throws Exception{var p=paid();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var service=adminReconcile(new DelegatingProvider(fake){@Override public ProviderState retrievePayment(ProviderPaymentLookup lookup){calls.incrementAndGet();entered.countDown();try{assertThat(release.await(5,TimeUnit.SECONDS)).isTrue();}catch(InterruptedException e){throw new AssertionError(e);}throw new AssertionError("crash after receipt and lease");}});try(var pool=Executors.newSingleThreadExecutor()){var first=pool.submit(()->service.reconcile(p.id(),actor,"concurrent","request"));assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();var receipt=jdbc.queryForMap("select * from idempotency_records");assertThatThrownBy(()->service.reconcile(p.id(),actor,"concurrent","request")).isInstanceOf(PaymentApplicationException.class).extracting("code").isEqualTo("PAYMENT_STATE_CONFLICT");assertThat(calls.get()).isEqualTo(1);release.countDown();assertThatThrownBy(()->first.get(5,TimeUnit.SECONDS)).hasCauseInstanceOf(AssertionError.class);dev.genericpayments.platform.support.PostgresIntegrationTest.TestClock.set(INITIAL_TIME.plusSeconds(31));adminReconcile(fake).reconcile(p.id(),actor,"concurrent","request");assertThat(jdbc.queryForMap("select * from idempotency_records")).isEqualTo(receipt);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_RECONCILIATION_REQUESTED'",Integer.class)).isEqualTo(1);}finally{release.countDown();}}
}
